import hashlib,json,os,subprocess,sys,tempfile,zipfile
from pathlib import Path
wheel=Path('.dev/mirror-inventory-wheel/pa-1.5.9-py3-none-any.whl');target=Path('.dev/mirror-inventory-wheel-runtime').resolve();assert not target.exists();hashes={}
with zipfile.ZipFile(wheel) as archive:
 for item in archive.infolist():
  path=Path(item.filename);assert not path.is_absolute() and '..' not in path.parts
  if item.filename.startswith('pa/') and not item.is_dir():
   data=archive.read(item);source=Path('src')/path
   if source.is_file():assert source.read_bytes()==data;hashes[str(source)]=hashlib.sha256(data).hexdigest()
   destination=target/path;destination.parent.mkdir(parents=True,exist_ok=True);destination.write_bytes(data)
 cache=archive.read('pa/server/template-bytecode.json');assert len(json.loads(cache)['entries'])==38
proof={'scope':'Actual437filecandidatewheel/29modulehashes/38templates with post-canonical indexed compatibility-mirror discovery; same100iteration mixed workload/5000expired events. Other expired-ID inventory scale is measured separately by30alternatingpairs. Allold failures/outliers remain; not deployed acceptance or causal whole-scenario comparison.','wheel_sha256':hashlib.sha256(wheel.read_bytes()).hexdigest(),'source_file_hashes':hashes,'cache_sha256':hashlib.sha256(cache).hexdigest(),'cache_entries':38,'baseline':'.dev/systemic-retention-baseline100.json','script_sha256':hashlib.sha256(Path('scripts/benchmark_systemic_latency.py').read_bytes()).hexdigest(),'runs':[]}
for label,source in [('mirror-inventory',target)]:
 with tempfile.TemporaryDirectory(prefix='pa-mirror-retention-'+label+'-') as temporary:
  env=os.environ.copy();env['PYTHONPATH']=str(source);env['PA_DATA_DIR']=str(Path(temporary)/'data');env['PA_WORKSPACE_ROOT']=str(Path(temporary)/'workspaces')
  output='.dev/systemic-retention-'+label+'100.json';log=Path('.dev/systemic-retention-'+label+'100.log')
  with log.open('w') as handle:
   result=subprocess.run([sys.executable,'scripts/benchmark_systemic_latency.py','--output',output,'--history','1000','--iterations','100','--inventory-reads','--retention-events','5000'],env=env,stdout=handle,stderr=subprocess.STDOUT)
  record={'label':label,'source':str(source),'exit_code':result.returncode,'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest(),'log':str(log),'output':output}
  if Path(output).exists():
   value=json.loads(Path(output).read_text());record.update(output_sha256=hashlib.sha256(Path(output).read_bytes()).hexdigest(),warnings=value['warnings'],violations=value['threshold_violations'],retention=value['fixture']['retention_outcome'],retained=value['transcript_retained_rows'])
   assert value['benchmark_script_sha256']==proof['script_sha256']
   for name,digest in value['source_module_sha256'].items():
    actual=hashlib.sha256((source/Path(name.replace('.','/')+'.py')).read_bytes()).hexdigest();assert actual==digest,name
   if label=='mirror-inventory':
    for name,digest in value['source_module_sha256'].items():assert hashes['src/'+name.replace('.','/')+'.py']==digest,name
  proof['runs'].append(record);Path('.dev/mirror-inventory-mixed-proof.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(record),flush=True)
  assert result.returncode==0,record
for name,digest in hashes.items():assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==digest,name

